package com.nexushr.controller; import com.nexushr.dto.RequestDtos.PayrollRequest; import com.nexushr.entity.Payroll; import com.nexushr.service.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.security.Principal; import java.time.*; import java.util.*; @RestController @RequestMapping("/payroll") public class PayrollController {final PayrollService s;final EmployeeService e;public PayrollController(PayrollService s,EmployeeService e){this.s=s;this.e=e;} @GetMapping("/me") public List<Payroll> mine(Principal p){return s.mine(p.getName(),e);} @GetMapping @PreAuthorize("hasAnyRole('ADMIN','HR')") public List<Payroll> month(@RequestParam YearMonth month){return s.month(month.toString());} @PostMapping("/employee/{id}") @PreAuthorize("hasAnyRole('ADMIN','HR')") public Payroll create(@PathVariable UUID id,@RequestBody PayrollRequest x){return s.create(id,x);}}
